await check('P13 提交身份生命周期及非法 grade 在判题、答案与摘要前失败',async()=>{const question={id:'same-id',subject:'math',grade:'grade1-term2',kind:'input',prompt:'1 + 1',answer:'2',sourceRef:{expr:'1 + 1',answer:'2',type:'add'},due:false};const args={grade:'grade1-term2',paperInstanceId:'a'.repeat(32),seed:'2026-09-01|grade1-term2|9|medium',questions:[question],answers:['2'],submittedAt:'2026-09-01T06:00:00.000Z'};const created=await paper.createPaperSubmissionIntent(args),samePageRetry=await paper.createPaperSubmissionIntent(args),afterRefresh=await paper.createPaperSubmissionIntent({...args,paperInstanceId:'b'.repeat(32)}),activeNewPaper=await paper.createPaperSubmissionIntent({...args,paperInstanceId:'c'.repeat(32)});assert.equal(created.grade,'grade1-term2');assert.equal(created.answers[0].correct,true);assert.match(created.submissionId,/^[a-f0-9]{64}$/);assert.equal(samePageRetry.submissionId,created.submissionId);assert.notEqual(afterRefresh.submissionId,created.submissionId);assert.notEqual(activeNewPaper.submissionId,created.submissionId);assert.notEqual(afterRefresh.submissionId,activeNewPaper.submissionId);let poisonedReads=0;const poisonedQuestions=new Proxy([question],{get(){poisonedReads++;throw new Error('QUESTIONS_MUST_NOT_BE_READ')}}),poisonedAnswers=new Proxy(['2'],{get(){poisonedReads++;throw new Error('ANSWERS_MUST_NOT_BE_READ')}});await assert.rejects(()=>paper.createPaperSubmissionIntent({...args,grade:'grade2',questions:poisonedQuestions,answers:poisonedAnswers}),/PAPER_SUBMISSION_INVALID/);assert.equal(poisonedReads,0);for(const wrongGrade of ['grade2',undefined]){let questionReads=0,answerReads=0;const invalidQuestion=new Proxy({...question,grade:wrongGrade},{get(target,key,receiver){if(key!=='grade')questionReads++;return Reflect.get(target,key,receiver)}}),answers=new Proxy(['2'],{get(target,key,receiver){answerReads++;throw new Error(`ANSWERS_${String(key)}_MUST_NOT_BE_READ`)}});await assert.rejects(()=>paper.createPaperSubmissionIntent({...args,questions:[invalidQuestion],answers}),/PAPER_SUBMISSION_INVALID/);assert.equal(questionReads,0,`${wrongGrade}:question`);assert.equal(answerReads,0,`${wrongGrade}:answers`)}});

await check('P10 全局年级、复合 key 与特殊控件接线',()=>{const page=readFileSync(resolve(root,'pages/learning/paper.vue'),'utf8');const home=readFileSync(resolve(root,'pages/index/index.vue'),'utf8');const component=readFileSync(resolve(root,'components/learning/PaperQuestion.vue'),'utf8');assert.match(home,/LEARNING_GRADE_OPTIONS/);assert.doesNotMatch(page,/grade-choices|selectGrade/);assert.match(page,/:key="`\$\{question\.subject\}:\$\{question\.id\}`"/);assert.match(page,/\$\{localDateString\(new Date\(\)\)\}\|\$\{sessionGrade\}\|\$\{count\.value\}\|\$\{difficulty\.value\}/);for(const type of ['fillOp','fillOp2','hundredChart','triangle-free'])assert.ok(component.includes(type));assert.doesNotMatch(component,/question\.(answer|sourceRef)/)});

