function candidates(subject,count,dueCount=0){return Array.from({length:count},(_,index)=>({id:`${subject}-${index}`,subject,grade:'grade1-term2',kind:'input',prompt:`${subject}${index}`,answer:String(index),sourceRef:{expr:`${index}+0`,answer:String(index),type:'add',question_id:`${subject}-${index}`},due:index<dueCount}))}
function specialCandidate(id,due=false){return{id,subject:'math',grade:'grade1-term2',kind:'math-special',mathType:'fillOp',prompt:'请完成填空',renderData:{a:1,b:2,c:3},answer:'+',sourceRef:{expr:'1 ○ 2 = 3',answer:'+',type:'fillOp'},due}}
await check('C02 最大余数、同余数稳定序与同 seed 稳定',()=>{const input={grade:'grade1-term2',stats:{math:{total:10,correct:10,dueCount:0},chinese:{total:10,correct:10,dueCount:0},english:{total:10,correct:10,dueCount:0}},candidates:{math:candidates('math',20),chinese:candidates('chinese',20),english:candidates('english',20)},count:9,difficulty:'medium',seed:'2026-08-29|grade1-term2|9|medium'};const first=paper.buildPaper(input),second=paper.buildPaper(input);assert.deepEqual(first.quotas,{math:3,chinese:3,english:3});assert.deepEqual(first.questions,second.questions)});

await check('C02 库存短缺按数学→语文→英语转移且 due 优先',()=>{const result=paper.buildPaper({grade:'grade1-term2',stats:{math:{total:0,correct:0,dueCount:0},chinese:{total:0,correct:0,dueCount:0},english:{total:0,correct:0,dueCount:0}},candidates:{math:candidates('math',20,2),chinese:candidates('chinese',1),english:candidates('english',20)},count:9,difficulty:'medium',seed:'x'});assert.equal(result.ok,true);assert.equal(result.quotas.chinese,1);assert.equal(result.quotas.math,5);assert.equal(result.questions.filter(item=>item.subject==='math'&&item.due).length,2);const shortage=paper.buildPaper({grade:'grade1-term2',stats:{math:{},chinese:{},english:{}},candidates:{math:candidates('math',2),chinese:candidates('chinese',2),english:candidates('english',2)},count:9,seed:'x'});assert.equal(shortage.code,'PAPER_INVENTORY_SHORTAGE')});

await check('P04 数学特殊题按稳定池在实际配额内保底',()=>{
  const equalQuotas={9:{math:3,chinese:3,english:3},12:{math:4,chinese:4,english:4},15:{math:5,chinese:5,english:5}};
  const buildInput=(mathCandidates,count=9,seed='candidate-0')=>({grade:'grade1-term2',stats:{math:{},chinese:{},english:{}},candidates:{math:mathCandidates,chinese:candidates('chinese',20),english:candidates('english',20)},count,difficulty:'medium',seed});
  const runStable=(input,label)=>{const before=structuredClone(input),first=paper.buildPaper(input),second=paper.buildPaper(input),expected=equalQuotas[input.count];assert.deepEqual(input,before,`${label}:输入不得被改写`);assert.deepEqual(first,second,`${label}:同输入必须逐题稳定`);assert.equal(first.questions.length,input.count,`${label}:总题量`);assert.deepEqual(first.quotas,expected,`${label}:实际配额`);assert.deepEqual(first.requestedQuotas,expected,`${label}:请求配额`);assert.deepEqual(Object.fromEntries(['math','chinese','english'].map(subject=>[subject,first.questions.filter(item=>item.subject===subject).length])),expected,`${label}:三科题数`);return first};
  const freshCases=[
    {count:9,seed:'candidate-0',mathIds:['math-0','math-3','special-fresh']},
    {count:12,seed:'candidate-1',mathIds:['math-1','math-2','math-4','special-fresh']},
    {count:15,seed:'candidate-4',mathIds:['math-1','math-4','math-6','math-8','special-fresh']},
  ];
  for(const item of freshCases){const input=buildInput([...candidates('math',9),specialCandidate('special-fresh')],item.count,item.seed),rawPool=paper.shuffleWithRng(input.candidates.math,paper.xorshift32(`${item.seed}|medium|math`)),displaced=rawPool[item.count/3-1],result=runStable(input,`fresh:${item.count}:${item.seed}`),mathQuestions=result.questions.filter(question=>question.subject==='math');assert.ok(rawPool.findIndex(question=>question.id==='special-fresh')>=result.quotas.math,`fresh:${item.count}:特殊题须从配额外保底`);assert.deepEqual(mathQuestions.map(question=>question.id).sort(),item.mathIds,`fresh:${item.count}:逐 ID oracle`);assert.equal(mathQuestions.some(question=>question.id===displaced.id),false,`fresh:${item.count}:原末席 ${displaced.id} 应后移`);assert.equal(mathQuestions.filter(question=>question.kind==='math-special').length,1,`fresh:${item.count}:特殊题数量`)}
  const dueFilledInput=buildInput([...candidates('math',10,10),specialCandidate('special-fresh')]);const dueFilled=runStable(dueFilledInput,'普通 due 填满');assert.deepEqual(dueFilled.questions.filter(item=>item.subject==='math').map(item=>item.id).sort(),['math-0','math-3','special-fresh']);assert.equal(dueFilled.questions.filter(item=>item.subject==='math'&&item.due).length,2,'特殊题保底必须优先于普通 due');
  const competeInput=buildInput([...candidates('math',10,10),specialCandidate('special-due',true),specialCandidate('special-fresh')],9,'s0'),competeRawPool=[...paper.shuffleWithRng(competeInput.candidates.math.filter(item=>item.due),paper.xorshift32('s0|medium|math')),...paper.shuffleWithRng(competeInput.candidates.math.filter(item=>!item.due),paper.xorshift32('s0|medium|math'))];assert.ok(competeRawPool.findIndex(item=>item.id==='special-due')>=3&&competeRawPool.findIndex(item=>item.id==='special-fresh')>=3,'due/fresh 特殊题都必须先位于配额外');const duePreferred=runStable(competeInput,'due/fresh 配额外竞争');assert.deepEqual(duePreferred.questions.filter(item=>item.subject==='math').map(item=>item.id).sort(),['math-4','math-5','special-due']);assert.deepEqual(duePreferred.questions.filter(item=>item.kind==='math-special').map(item=>item.id),['special-due']);
  const insideInput=buildInput([specialCandidate('special-in',true),...candidates('math',12,5)],9,'inside-1'),insideRawPool=[...paper.shuffleWithRng(insideInput.candidates.math.filter(item=>item.due),paper.xorshift32('inside-1|medium|math')),...paper.shuffleWithRng(insideInput.candidates.math.filter(item=>!item.due),paper.xorshift32('inside-1|medium|math'))];assert.ok(insideRawPool.findIndex(item=>item.id==='special-in')>=0&&insideRawPool.findIndex(item=>item.id==='special-in')<3,'特殊题必须在保底前已经位于数学配额内');const inside=runStable(insideInput,'配额内已有特殊题');assert.deepEqual(inside.questions.map(item=>`${item.subject}:${item.id}`),['chinese:chinese-10','english:english-9','chinese:chinese-3','english:english-17','english:english-0','math:special-in','math:math-4','chinese:chinese-7','math:math-2']);
  const noSpecialInput=buildInput(candidates('math',12,5),9,'none-0'),noSpecial=runStable(noSpecialInput,'无特殊候选');assert.deepEqual(noSpecial.questions.map(item=>`${item.subject}:${item.id}`),['chinese:chinese-0','math:math-2','english:english-0','chinese:chinese-1','math:math-4','math:math-1','english:english-13','english:english-11','chinese:chinese-4']);assert.equal(noSpecial.questions.some(item=>item.kind==='math-special'),false)
});

function snapshot(){const value=Object.fromEntries(registry.BACKUP_STORAGE_KEYS.map(key=>[key,{present:false}]));value[registry.STORAGE_KEYS.learningGrade]={present:true,value:{schemaVersion:1,grade:'grade1-term2'}};return value}
function hexToken(id,length=64){const nibble=(String(id).charCodeAt(0)%16).toString(16);return nibble.repeat(length)}
function reducerQuestion(subject,id,source,due=false){const answer=subject==='math'?source.answer:subject==='english'?'cat':'zhōng',sourceRef=subject==='math'?source:{...source,qType:'paper'};return{id,subject,grade:'grade1-term2',kind:subject==='math'?'input':'choice',prompt:subject==='math'?source.expr:id,answer,due,sourceRef,...(subject==='math'?{}:{options:[{label:answer,value:answer}]})}}
async function intent(id='A'){const questions=[reducerQuestion('math','m1',{expr:'1 + 1',answer:'2',type:'add'}),reducerQuestion('chinese','c1',{question_id:'c1',type:'pinyin',char:'中',unit:'1'}),reducerQuestion('english','e1',{question_id:'e1',type:'word',word:'cat',theme:'animals'})],answers=['3','x','cat'];return paper.createPaperSubmissionIntent({grade:'grade1-term2',paperInstanceId:hexToken(id,32),seed:`fixture-${id}`,submittedAt:'2026-08-29T08:00:00.000Z',questions,answers})}
await check('C02 交卷含 grade 三收据幂等且冲突收据阻断',async()=>{const caseIntent=await intent('A'),first=paper.buildPaperSubmissionTarget(snapshot(),caseIntent);assert.equal(first.status,'TARGET_READY');const target=first.target;assert.equal(target[registry.STORAGE_KEYS.chinesePracticeLogs].value.length,1);assert.equal(target[registry.STORAGE_KEYS.englishPracticeLogs].value.length,1);assert.equal(JSON.parse(target[registry.STORAGE_KEYS.mathHistory].value).length,1);assert.ok([target[registry.STORAGE_KEYS.chinesePracticeLogs].value[0],target[registry.STORAGE_KEYS.englishPracticeLogs].value[0],JSON.parse(target[registry.STORAGE_KEYS.mathHistory].value)[0]].every(item=>item.grade==='grade1-term2'));const retry=paper.buildPaperSubmissionTarget(target,caseIntent);assert.equal(retry.status,'ALREADY_COMMITTED');const missing=structuredClone(target);missing[registry.STORAGE_KEYS.englishPracticeLogs].value=[];assert.equal(paper.buildPaperSubmissionTarget(missing,caseIntent).status,'PAPER_SUBMISSION_INCONSISTENT');const duplicate=structuredClone(target);duplicate[registry.STORAGE_KEYS.chinesePracticeLogs].value.push(structuredClone(duplicate[registry.STORAGE_KEYS.chinesePracticeLogs].value[0]));assert.equal(paper.buildPaperSubmissionTarget(duplicate,caseIntent).status,'PAPER_SUBMISSION_INCONSISTENT');const conflict=structuredClone(target);conflict[registry.STORAGE_KEYS.chinesePracticeLogs].value[0].grade='grade2';assert.equal(paper.buildPaperSubmissionTarget(conflict,caseIntent).status,'PAPER_SUBMISSION_INCONSISTENT')});

