await check('P15 确认/取消窗口由 busy 门禁完整包围',()=>{const page=readFileSync(resolve(root,'pages/learning/paper.vue'),'utf8');const submitBody=page.slice(page.indexOf('async function submit()'),page.indexOf('\nfunction reset()'));const busyIndex=submitBody.indexOf('busy.value = true'),modalIndex=submitBody.indexOf('uni.showModal'),cancelIndex=submitBody.indexOf('if (!confirmed) return'),intentIndex=submitBody.indexOf('createPaperSubmissionIntent'),mutationIndex=submitBody.indexOf('session.runPaperMutation');assert.ok(busyIndex>=0&&busyIndex<modalIndex,'busy 必须在打开确认弹窗前置为 true');assert.ok(cancelIndex>modalIndex&&cancelIndex<intentIndex&&cancelIndex<mutationIndex,'取消必须在 intent 和 mutation 前零写返回');assert.equal((submitBody.match(/createPaperSubmissionIntent/g)||[]).length,1);assert.match(submitBody,/finally\s*\{\s*busy\.value = false\s*\}/s)});

