await check('P14 fresh/due×正确/错误×三科完整错题与聚合收据矩阵',async()=>{const configs={
  chinese:{key:registry.STORAGE_KEYS.chineseMistakes,json:false,source:{question_id:'c-matrix',type:'pinyin',char:'中',unit:'1'},existing:{grade:'grade1-term2',_id:'c-matrix',question_id:'c-matrix',type:'pinyin',char:'中',unit:'1',wrongCount:4,correctCount:0,box:1,nextReviewAt:1,mastered:false,lastWrongAt:1,createdAt:1},match:item=>item.question_id==='c-matrix'},
  english:{key:registry.STORAGE_KEYS.englishMistakes,json:false,source:{question_id:'e-matrix',type:'word',word:'cat',theme:'animals'},existing:{grade:'grade1-term2',_id:'e-matrix',question_id:'e-matrix',type:'word',word:'cat',theme:'animals',wrongCount:4,correctCount:0,box:1,nextReviewAt:1,mastered:false,lastWrongAt:1,createdAt:1},match:item=>item.question_id==='e-matrix'},
  math:{key:registry.STORAGE_KEYS.mathWrongBook,json:true,source:{expr:'7 + 1',answer:'8',type:'add'},existing:{grade:'grade1-term2',id:'m-matrix',expr:'7 + 1',answer:'8',type:'add',wrongCount:4,correctCount:0,box:1,nextReviewAt:1,mastered:false,lastWrongAt:1,createdAt:1},match:item=>item.expr==='7 + 1'},
};for(const [subject,config] of Object.entries(configs))for(const due of [false,true])for(const correct of [false,true]){const original=snapshot(),initial=due?[structuredClone(config.existing)]:[];original[config.key]={present:true,value:config.json?JSON.stringify(initial):initial};const submittedAt='2026-09-01T06:00:00.000Z',now=Date.parse(submittedAt),questionId=subject==='math'?`${subject}-matrix`:config.source.question_id,question=reducerQuestion(subject,questionId,config.source,due),userAnswer=correct?question.answer:'bad',caseIntent=await paper.createPaperSubmissionIntent({grade:'grade1-term2',paperInstanceId:hexToken(`${subject}-instance`,32),seed:`matrix-${subject}-${due}-${correct}`,submittedAt,questions:[question],answers:[userAnswer]}),submissionId=caseIntent.submissionId;const result=paper.buildPaperSubmissionTarget(original,caseIntent);assert.equal(result.status,'TARGET_READY');const wrongLists={chinese:result.target[registry.STORAGE_KEYS.chineseMistakes].value,english:result.target[registry.STORAGE_KEYS.englishMistakes].value,math:JSON.parse(result.target[registry.STORAGE_KEYS.mathWrongBook].value)};for(const other of Object.keys(wrongLists))if(other!==subject)assert.deepEqual(wrongLists[other],[],`${subject}/${due}/${correct}:other-${other}`);if(correct)assert.deepEqual(wrongLists[subject],initial,`${subject}/${due}/correct`);else{const expected=due?{...config.existing,wrongCount:5,correctCount:0,box:1,nextReviewAt:now+86400000,mastered:false,lastWrongAt:now}:subject==='math'?{grade:'grade1-term2',id:`paper_${questionId}`,expr:config.source.expr,answer:config.source.answer,type:config.source.type,wrongCount:1,correctCount:0,box:1,nextReviewAt:now+86400000,mastered:false,lastWrongAt:now,createdAt:now}:{...config.source,qType:'paper',grade:'grade1-term2',_id:config.source.question_id,question_id:config.source.question_id,wrongCount:1,correctCount:0,box:1,nextReviewAt:now+86400000,mastered:false,lastWrongAt:now,createdAt:now};assert.deepEqual(wrongLists[subject],[expected],`${subject}/${due}/wrong`)}const receipts={chinese:result.target[registry.STORAGE_KEYS.chinesePracticeLogs].value,english:result.target[registry.STORAGE_KEYS.englishPracticeLogs].value,math:JSON.parse(result.target[registry.STORAGE_KEYS.mathHistory].value)};for(const [receiptSubject,list] of Object.entries(receipts)){assert.equal(list.length,1,`${subject}/${receiptSubject}:receipt-count`);const receipt=list[0];assert.equal(receipt.submissionId,submissionId);assert.equal(receipt.type,'paper');assert.equal(receipt.grade,'grade1-term2');assert.equal(receipt.totalCount,receiptSubject===subject?1:0);assert.equal(receipt.correctCount,receiptSubject===subject&&correct?1:0)}assert.equal(Object.values(receipts).reduce((sum,list)=>sum+list[0].totalCount,0),1);assert.equal(Object.values(receipts).reduce((sum,list)=>sum+list[0].correctCount,0),correct?1:0)}});

await check('P03 看板与组卷从重复原始 due 共用去重解析口径',()=>{assert.notEqual(paperSourcesStart,-1);const missing=[],chineseDue={question_id:'pinyin_中_2-1-1'},englishDue={question_id:'word_animals_cat'},mathDue={expr:'1 + 1',answer:'2',type:'add'};const due={chinese:[chineseDue,structuredClone(chineseDue),{question_id:'missing-cn'}],english:[englishDue,structuredClone(englishDue),{question_id:'missing-en'}],math:[mathDue,structuredClone(mathDue),{expr:'',answer:'2',type:'add'}]};const result=paperSourcesModule.resolveDashboardDue(due,(code,module)=>missing.push({code,module}));assert.deepEqual(Object.fromEntries(Object.entries(result).map(([key,value])=>[key,value.length])),{chinese:1,math:1,english:1});const dashboard=stats.buildLearningDashboard({chineseLogs:[],englishLogs:[],mathHistory:[],chineseDue:result.chinese.length,englishDue:result.english.length,mathDue:result.math.length,goal:null,challenge:null},new Date('2026-09-01T12:00:00'));assert.equal(dashboard.dueCount,3);const paperSources=paperSourcesModule.buildAllPaperSources({grade:'grade1-term2',difficulty:'medium',seed:'fixed',due:result,onMissing:(code,module)=>missing.push({code,module})});assert.deepEqual(Object.fromEntries(['chinese','math','english'].map(subject=>[subject,paperSources.candidates[subject].filter(item=>item.due).length])),{chinese:1,math:1,english:1});assert.equal(paperSources.candidates.math.filter(item=>item.due&&item.id==='add_1 + 1').length,1);const forgedMissing=[];const forged=paperSourcesModule.buildAllPaperSources({grade:'grade1-term2',difficulty:'medium',seed:'fixed',due:{math:[{expr:'',answer:'2',type:'add',question_id:'add_1 + 1'}]},onMissing:(code,module)=>forgedMissing.push({code,module})});assert.equal(forged.candidates.math.filter(item=>item.due).length,0);assert.deepEqual(forgedMissing,[{code:'PAPER_SOURCE_MISSING',module:'paper'}]);assert.equal(missing.length,3);assert.ok(missing.every(item=>item.code==='PAPER_SOURCE_MISSING'&&item.module==='paper'))});

await check('F04 数学专注 reducer 同提交幂等且同时更新两类存储',async()=>{const original=snapshot();original[registry.STORAGE_KEYS.mathHistory]={present:true,value:'[]'};original[registry.STORAGE_KEYS.mathWrongBook]={present:true,value:'[]'};const created=await mathStorage.createFocusSubmissionIntent({grade:'grade1-term2',focusInstanceId:'instance-A',submittedAt:'2026-08-29T08:00:00.000Z',answers:[{expr:'1 + 1',answer:'2',type:'add',userAnswer:'3',correct:false}]});assert.match(created.submissionDigest,/^[a-f0-9]{64}$/);const intent={sessionGrade:'grade1-term2',grade:'grade1-term2',submissionId:'focus-A',submissionDigest:'digest-A',submittedAt:'2026-08-29T08:00:00.000Z',answers:[{expr:'1 + 1',answer:'2',type:'add',userAnswer:'3',correct:false},{expr:'2 + 2',answer:'4',type:'add',userAnswer:'4',correct:true}]};const first=mathStorage.buildFocusSubmissionTarget(original,intent);assert.equal(first.status,'TARGET_READY');const retry=mathStorage.buildFocusSubmissionTarget(first.target,intent);assert.equal(retry.status,'ALREADY_COMMITTED');const history=JSON.parse(first.target[registry.STORAGE_KEYS.mathHistory].value),wrong=JSON.parse(first.target[registry.STORAGE_KEYS.mathWrongBook].value);assert.equal(history.filter(item=>item.submissionId==='focus-A').length,1);assert.equal(wrong.filter(item=>item.expr==='1 + 1').length,1)});

await check('C06 诊断不输出存储值/query/stack且所有路由来源去参',()=>{const values=new Map([[registry.STORAGE_KEYS.chineseState,{secret:'SENSITIVE_BODY'}]]);const storage={getStorageSync:key=>values.has(key)?values.get(key):''};const base={appVersion:'1.0.0',storageApi:storage,errors:[{at:'2026-08-29T00:00:00Z',code:'UNKNOWN_CONTROLLED_ERROR',module:'app',message:'SENSITIVE_STACK'}],clock:()=>new Date('2026-08-29T01:00:00Z')};const report=diagnostics.buildDiagnosticReport({...base,env:{navigator:{userAgent:'ua',language:'zh-CN',onLine:true},innerWidth:390,innerHeight:844,location:{hash:'#/pages/learning/dashboard?token=SENSITIVE_TOKEN'}}});const pagesReport=diagnostics.buildDiagnosticReport({...base,env:{navigator:{userAgent:'ua',language:'zh-CN',onLine:true},innerWidth:390,innerHeight:844,getCurrentPages:()=>[{route:'pages/learning/paper?token=SENSITIVE_TOKEN#part'}],location:{hash:''}}});const output=JSON.stringify([report,pagesReport]);assert.equal(report.route,'/pages/learning/dashboard');assert.equal(pagesReport.route,'/pages/learning/paper');assert.equal(output.includes('SENSITIVE_BODY'),false);assert.equal(output.includes('SENSITIVE_STACK'),false);assert.equal(output.includes('SENSITIVE_TOKEN'),false);assert.deepEqual(report.storage.map(item=>item.key),[...report.storage.map(item=>item.key)].sort())});

await check('C02/F07 看板字段与专注原子失败提示已接线',()=>{const dashboard=readFileSync(resolve(root,'pages/learning/dashboard.vue'),'utf8');assert.match(dashboard,/dashboard\.today\.correct/);assert.match(dashboard,/day\.subjects\[subject\.key\]\.correct/);assert.match(dashboard,/resolveDashboardDue/);const focus=readFileSync(resolve(root,'pages/math/focus.vue'),'utf8');assert.match(focus,/session\.runPaperMutation/);assert.match(focus,/applyRegisteredSnapshotTransaction/);assert.match(focus,/frozenIntent/);assert.match(focus,/error\?\.committed/);assert.match(focus,/记录已保存，但存储状态需要恢复/);assert.match(focus,/专注记录未保存/);assert.doesNotMatch(focus,/saveRecord|recordWrong/);const storage=readFileSync(resolve(root,'utils/math/mathStorage.js'),'utf8');assert.match(storage,/export function buildFocusSubmissionTarget/);assert.match(storage,/status: 'ALREADY_COMMITTED'/)});

await check('F01-F04 页面与入口接线完整',()=>{const pages=readFileSync(resolve(root,'pages.json'),'utf8');for(const route of ['pages/learning/dashboard','pages/learning/data-center','pages/learning/paper','pages/math/focus'])assert.ok(pages.includes(route));const main=readFileSync(resolve(root,'main.js'),'utf8');assert.match(main,/installLearningSessionGate/);assert.match(readFileSync(resolve(root,'pages/index/index.vue'),'utf8'),/learning\/dashboard/)});

